pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public {
        c = new C();
    }

    function testFuzz_property(address owner) public {
        vm.assume(owner != address(0));

        MockFeed feed = new MockFeed();
        MockToken coll = new MockToken("Coll", "COL");
        MockToken borr = new MockToken("Borr", "BOR");
        MockPool pool = new MockPool();

        C.InitializeFeeConfigParams memory f = C.InitializeFeeConfigParams({
            swapFeeAPR: 0,
            fragmentationFee: 0,
            liquidationRewardPercent: 0,
            overdueCollateralProtocolPercent: 0,
            collateralProtocolPercent: 0,
            feeRecipient: owner
        });
        C.InitializeRiskConfigParams memory r = C.InitializeRiskConfigParams({
            crOpening: 2e18,
            crLiquidation: 1500e15,
            minimumCreditBorrowAToken: 1,
            borrowATokenCap: type(uint256).max,
            minTenor: 1,
            maxTenor: 2
        });
        C.InitializeOracleParams memory o = C.InitializeOracleParams({
            priceFeed: address(feed),
            variablePoolBorrowRateStaleRateInterval: 1
        });
        C.InitializeDataParams memory d = C.InitializeDataParams({
            weth: address(new MockToken("WETH", "WETH")),
            underlyingCollateralToken: address(coll),
            underlyingBorrowToken: address(borr),
            variablePool: address(pool)
        });

        vm.prank(owner);
        c.initialize(owner, f, r, o, d);

        // before pausing, entry points work
        bool okBefore;
        try c.multicall(new bytes[](0)) {
            okBefore = true;
        } catch {
            okBefore = false;
        }
        assertTrue(okBefore);

        vm.prank(owner);
        c.pause();

        // GENERAL RULE: after pause(), every whenNotPaused entry (e.g. multicall) must revert
        bool okAfter;
        try c.multicall(new bytes[](0)) {
            okAfter = true;
        } catch {
            okAfter = false;
        }
        assertTrue(!okAfter);
    }
}

