pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address owner) public {
        vm.assume(owner != address(0));

        // initialize the protocol (grants roles to owner) if possible
        C.InitializeFeeConfigParams memory f = C.InitializeFeeConfigParams({
            swapFeeAPR: 0,
            fragmentationFee: 0,
            liquidationRewardPercent: 0,
            overdueCollateralProtocolPercent: 0,
            collateralProtocolPercent: 0,
            feeRecipient: address(0xBEEF)
        });
        C.InitializeRiskConfigParams memory r = C.InitializeRiskConfigParams({
            crOpening: 1.5e18,
            crLiquidation: 1.2e18,
            minimumCreditBorrowAToken: 1,
            borrowATokenCap: type(uint256).max,
            minTenor: 1,
            maxTenor: 2
        });
        PriceFeed pf = new PriceFeed();
        C.InitializeOracleParams memory o = C.InitializeOracleParams({
            priceFeed: address(pf),
            variablePoolBorrowRateStaleRateInterval: 1 days
        });
        Tok tok = new Tok();
        C.InitializeDataParams memory d = C.InitializeDataParams({
            weth: address(new Tok()),
            underlyingCollateralToken: address(tok),
            underlyingBorrowToken: address(tok),
            variablePool: address(0xCAFE)
        });

        vm.prank(owner);
        try c.initialize(owner, f, r, o, d) {
            // initialization succeeded
        } catch {
            // not initialized; the property must still hold for the reachable state
        }

        // drive c through `pause` and observe `paused`
        vm.prank(owner);
        bool pauseSucceeded;
        try c.pause() {
            pauseSucceeded = true;
        } catch {
            pauseSucceeded = false;
        }

        // GENERAL RULE: if pause() succeeded, paused() MUST report true;
        // if pause() reverted, the contract must remain unpaused (false).
        assertTrue(c.paused() == pauseSucceeded);
    }
}

