// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C, InitializeFeeConfigParams, InitializeRiskConfigParams, InitializeOracleParams, InitializeDataParams} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public {
        c = new C();
        c.initialize(
            address(this),
            InitializeFeeConfigParams({
                swapFeeAPR: 0,
                fragmentationFee: 0,
                liquidationRewardPercent: 0,
                overdueCollateralProtocolPercent: 0,
                collateralProtocolPercent: 0,
                feeRecipient: address(0xfee1)
            }),
            InitializeRiskConfigParams({
                crOpening: 1.5e18,
                crLiquidation: 1e18,
                minimumCreditBorrowAToken: 1,
                borrowATokenCap: type(uint256).max,
                minTenor: 1,
                maxTenor: 365 days
            }),
            InitializeOracleParams({
                priceFeed: address(new MockPriceFeed()),
                variablePoolBorrowRateStaleRateInterval: 1 days
            }),
            InitializeDataParams({
                weth: address(new MockERC20()),
                underlyingCollateralToken: address(new MockERC20()),
                underlyingBorrowToken: address(new MockERC20()),
                variablePool: address(new MockERC20())
            })
        );
    }

    // General rule: for any (irrelevant) fuzz input, once a PAUSER_ROLE holder's pause()
    // has succeeded, the protocol must be paused, so a SECOND pause() call by the same
    // PAUSER_ROLE holder must revert with EnforcedPause. The buggy contract reports
    // paused() == false even after pausing, so the second pause() silently succeeds.
    function testFuzz_property(uint256 seed) public {
        // keep the parameter in the admissible domain (wide)
        seed = bound(seed, 0, type(uint256).max - 1);

        // first pause by the PAUSER_ROLE holder succeeds
        c.pause();

        // a second pause must revert because the contract is paused
        bool ok;
        try c.pause() {
            ok = true;
        } catch {
            ok = false;
        }
        assertTrue(!ok, "second pause must revert while paused");
    }
}

contract MockPriceFeed {
    function getPrice() external pure returns (uint256) {
        return 1e18;
    }

    function decimals() external pure returns (uint8) {
        return 18;
    }
}

contract MockERC20 {
    function decimals() external pure returns (uint8) {
        return 18;
    }
}
